CREATE TABLE public.flow_templates (
  id text PRIMARY KEY,
  name text NOT NULL,
  description text NOT NULL DEFAULT '',
  category text NOT NULL,
  icon text NOT NULL DEFAULT 'Sparkles',
  nodes jsonb NOT NULL DEFAULT '[]'::jsonb,
  edges jsonb NOT NULL DEFAULT '[]'::jsonb,
  is_public boolean NOT NULL DEFAULT true,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now()
);

GRANT SELECT ON public.flow_templates TO anon;
GRANT SELECT ON public.flow_templates TO authenticated;
GRANT ALL ON public.flow_templates TO service_role;

ALTER TABLE public.flow_templates ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Public templates are readable by everyone"
ON public.flow_templates FOR SELECT
USING (is_public = true);

CREATE TRIGGER flow_templates_touch_updated_at
BEFORE UPDATE ON public.flow_templates
FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();

INSERT INTO public.flow_templates (id, name, description, category, icon, nodes, edges, is_public) VALUES
  ('ban-command', 'Ban Command', 'Prebuilt moderation workflow triggered by /ban.', 'Moderation', 'Sparkles', '[{"key":"cmd","type":"slash-command","x":0,"y":0,"title":"/ban","config":{"name":"ban","description":"Ban a member from the server."},"options":[{"id":"opt_mt8lgoee_1n0if","name":"user","description":"Member to ban","type":"user","required":true,"autocomplete":false},{"id":"opt_mt8lgoee_2m765","name":"reason","description":"Reason for the ban","type":"string","required":false,"autocomplete":false}]},{"key":"perm","type":"check-permission","x":0,"y":190,"config":{"permission":"BanMembers","user":"{user}"}},{"key":"ban","type":"ban-user","x":-190,"y":400,"config":{"user":"{user}","reason":"{reason}"}},{"key":"ok","type":"send-embed","x":-190,"y":600,"embed":{"id":"emb_mt8lgoee_3wltu","author":{"name":"","icon":"","url":""},"title":"🔨 User banned","description":"{user} has been banned.\n**Reason:** {reason}","url":"","color":"#ED4245","thumbnail":"","image":"","fields":[],"footer":{"text":"Bottly moderation","icon":""},"timestamp":true},"components":[{"id":"cmp_mt8lgoee_44lzk","type":"button","label":"Appeal","style":"secondary","emoji":"","action":"open_ticket","url":"","disabled":false,"placeholder":"Click me","options":[]}]},{"key":"err","type":"send-embed","x":260,"y":400,"title":"Send Error Embed","config":{"ephemeral":true},"embed":{"id":"emb_mt8lgoee_5fkts","author":{"name":"","icon":"","url":""},"title":"Missing permission","description":"You need the **Ban Members** permission to use this command.","url":"","color":"#F0B232","thumbnail":"","image":"","fields":[],"footer":{"text":"","icon":""},"timestamp":false}}]'::jsonb, '[{"from":"cmd","to":"perm"},{"from":"perm","to":"ban","handle":"true"},{"from":"perm","to":"err","handle":"false"},{"from":"ban","to":"ok"}]'::jsonb, true),
